import os
B=os.path.dirname(os.path.abspath(__file__))

def poe(q, opts, ans, exp):
    return ('      <div class="poe" data-q="%s"\n           data-opts="%s"\n           data-ans="%d"\n           data-exp="%s"></div>\n')%(q,'||'.join(opts),ans,exp)

