KIND={'RE':('R&amp;E','b-exp','wf_re'),'CR':('창의','b-poe','wf_cr'),'IN':('발명','b-uni','wf_in')}

def build(n, d):
    pre=d['pre']; kn=KIND[d['kind']]
    o=[]
    o.append('<!-- ═══════════════════════════════════════════════════════════════════════════\n     TAB %d — %s (%s · 카드 5개 · 고르면 장치 도해 · 예산 · 방법 · 예측 결과 · 미니 모의실험 · 실패 대처 · 평가가 펼쳐짐)\n     ═══════════════════════════════════════════════════════════════════════════ -->'%(n,d['title'],d['ids']))
    o.append('<section class="panel" id="tab%d" role="tabpanel" aria-labelledby="tabbtn%d" tabindex="0">'%(n,n))
    o.append('  <div class="card">')
    o.append('    <div class="h3"><span class="badge b-exp">%s</span><span class="badge b-high">고등</span><span class="badge b-poe">POE</span>%s %s</div>'%(d['badge'],d['icon'],d['title']))
    o.append('    <div class="goal">🎯 %s</div>'%d['goal'])
    o.append('    <div class="organizer">\n      <div class="ot">%s</div>\n      %s\n      <div class="bridge">%s</div>\n    </div>'%(d['org_t'],d['org'],'<span class="ar">→</span>'.join('<span class="st%s">%s</span>'%(' old' if i==0 else (' new' if i==len(d['bridge'])-1 else ''),b) for i,b in enumerate(d['bridge']))))
    o.append('  </div>\n')
    o.append('  <div class="card">')
    o.append('    <div class="h3">🧭 공방 안내 — 이렇게 진행합니다 <span class="badge b-mid">중등부터</span></div>')
    o.append('    <div class="figwrap">\n      <svg class="fig" viewBox="0 0 780 262" role="img" aria-label="%s 진행 흐름. 여섯 단계가 이어지고 되돌아가 고친다.">\n        {{FIG:%s}}\n      </svg>\n    </div>'%(kn[0],kn[2]))
    o.append('    <div class="figcap">그림 %d-1. %s 의 흐름 — 여섯 단계를 거치며 <b>되돌아가 고치는</b> 것이 핵심이다</div>'%(n,kn[0]))
    o.append('    <div class="h4">🧰 이 공방의 도구와 역할</div>\n    <div class="parts">')
    for t,x in d['parts']: o.append('      <div class="part"><b>%s</b>%s</div>'%(t,x))
    o.append('    </div>\n    <div class="h4">🧪 진행 순서</div>\n    <div class="steps">')
    for s in d['steps']: o.append('      <div class="step">%s</div>'%s)
    o.append('    </div>')
    o.append('    <div class="easy">\n      <div class="et">%s</div>\n      %s\n      <div class="compare">\n        <div class="cmp no"><b>❌ 이렇게 생각하기 쉬워요</b>%s</div>\n        <div class="cmp ok"><b>✅ 실제로는</b>%s</div>\n      </div>\n    </div>'%(d['easy_t'],d['easy'],d['no'],d['ok']))
    o.append('  </div>\n')
    o.append('  <div class="card">\n    <div class="h3">🗂 프로젝트 5선 (%s) — 카드를 누르면 아래에 자세한 안내가 펼쳐집니다</div>\n    <div class="tline" id="%s-pick" role="group" aria-label="프로젝트 고르기"></div>\n  </div>\n'%(d['title'].split(' ',2)[2] if False else d['badge'],pre))
    o.append('  <div id="%s-d1"></div>\n'%pre)
    o.append('  <div class="grid2">\n    <div>\n      <div class="card">')
    o.append('        <div class="h3">🎛 미니 모의실험 — <span id="%s-simT">—</span></div>\n        <p class="muted" id="%s-simQ">—</p>'%(pre,pre))
    for k in 'ab':
        o.append('        <div class="ctrl">\n          <div class="ctrl-top"><span class="nm" id="%s-%sN">—</span><span class="vl" id="%s-%sV">—</span></div>\n          <input type="range" id="%s-%s" min="0" max="1" step="0.01" value="0.5" aria-label="모의실험 변인 %s">\n        </div>'%(pre,k,pre,k,pre,k,'1' if k=='a' else '2'))
    o.append('        <div class="row">\n          <button type="button" class="btn sm pri" id="%s-go">🎲 새로 측정 (새 난수)</button>\n          <button type="button" class="btn sm" id="%s-def">↺ 기본값</button>\n        </div>\n        <div class="kv" id="%s-kv"></div>\n        <p class="tiny" id="%s-note">—</p>\n      </div>'%(pre,pre,pre,pre))
    for q,opts,ans,exp in d['poes']: o.append(poe(q,opts,ans,exp).rstrip('\n'))
    o.append('      <div id="%s-misc"></div>\n      <div class="hintbox" data-hints="%s"></div>\n    </div>'%(pre,d['hints']))
    o.append('    <div>\n      <div class="card tight">\n        <div class="cv-wrap">\n          <div class="cv-tools"><button type="button" class="btn sm fsb" data-fsx="%s" title="전체화면으로 보기 (수업용)">⛶ 전체화면</button><button type="button" class="btn sm" data-png="%s-cv" data-pngname="project-%d-sim">🖼 PNG</button></div>\n          <canvas id="%s-cv" role="img" aria-label="프로젝트 미니 모의실험 애니메이션" style="height:%dpx"></canvas>\n          <div class="cv-cap" id="%s-cap1">—</div>\n        </div>\n        <div id="%s-time"></div>\n        <div class="cv-wrap" style="margin-top:9px">\n          <canvas id="%s-cv2" role="img" aria-label="프로젝트 예상 결과 그래프" style="height:%dpx"></canvas>\n          <div class="cv-cap" id="%s-cap2">—</div>\n        </div>\n      </div>\n    </div>\n  </div>\n'%(pre,pre,n,pre,d['cvh'],pre,pre,pre,d['cv2h'],pre))
    o.append('  <div id="%s-d2"></div>\n</section>\n'%pre)
    return '\n'.join(o)

for n,d in TABS.items():
    open(os.path.join(B,'parts','t%02d.html'%n),'w',encoding='utf-8').write(build(n,d))
print('workshop tabs written:', sorted(TABS))
